"use strict";

// RWF-028's canonical C07. The package's whole callable API is chosen AT
// RUNTIME, and the statement that decides it is a ONE-HOP CONST ALIAS:
//
//     const alias = bail;
//     alias();
//
// Everything RWF-016 needs was already here and already proven: `bail` is
// a local, never-reassigned function declaration whose body throws on
// every path. The one thing RWF-016 could not do is say WHICH function
// `alias()` enters -- and on that alone it kept the later export's
// authority, bound the whole exported value to `safeOp`, gave the
// entrypoint's `fixture(input)` call a fully RESOLVED edge to it, left
// `dangerousOp` with no incoming edge, and answered NOT_AFFECTED with a
// COMPLETE Family C proof for a package that reaches the sink on every
// load taking the early branch.
//
// See fixtures/commonjs-circular-import-invocation-provenance-ground-truth/
// for a real node-executed, ASSERTED proof that the aliased call enters
// `bail`'s own body, that a cyclic `require()` retains `dangerousOp` by
// identity, and that `module.exports = safeOp` never runs.
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not.
function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("boom");
}

// The alias. Same function object as `bail`, by the language's own rules.
const alias = bail;

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  alias();
}

module.exports = safeOp;
